python3 - << 'PYEOF'
import os, py_compile, filecmp, sys, subprocess, json, pathlib

t = os.environ["TARGET_DIR"]
o = os.environ["ORIGINAL_DIR"]

# Syntax check modified python files
for root, dirs, files in os.walk(t):
    dirs[:] = [d for d in dirs if d not in (".git", "__pycache__")]
    for f in files:
        if f.endswith(".py"):
            tp = pathlib.Path(root) / f
            rel = tp.relative_to(t)
            op = pathlib.Path(o) / rel
            if not op.exists() or not filecmp.cmp(str(tp), str(op), shallow=False):
                try:
                    py_compile.compile(str(tp), doraise=True)
                except Exception as e:
                    print("Syntax error in", tp, e)
                    sys.exit(1)
print("Syntax: OK")
PYEOF

